begin;
do $$
declare boss uuid:=gen_random_uuid();supervisor uuid:=gen_random_uuid();employee uuid:=gen_random_uuid();late uuid:=gen_random_uuid();outsider uuid:=gen_random_uuid();owner_id uuid;c uuid;other_c uuid;l uuid;l2 uuid;d uuid;d2 uuid;w uuid;sw uuid;nw public.company_workers;v_shift uuid;v_ids uuid[];v_retry uuid[];v_request uuid:=gen_random_uuid();denied boolean;v_roster jsonb;invite jsonb;
begin
 insert into auth.users(id,email,email_confirmed_at) values(boss,boss||'@test.invalid',now()),(supervisor,supervisor||'@test.invalid',now()),(employee,employee||'@test.invalid',now()),(late,late||'@test.invalid',now()),(outsider,outsider||'@test.invalid',now());
 perform set_config('request.jwt.claim.sub',boss::text,true);
 c:=public.create_company_for_edition('Planning acceptance','essential');update public.companies set billing_status='active',seat_limit=10 where id=c;
 select id into l from public.essential_locations where company_id=c;if l is null then raise exception 'Default location missing';end if;
 insert into public.company_members(company_id,user_id,role) values(c,supervisor,'employee'),(c,employee,'employee');
 select id into sw from public.company_workers where company_id=c and auth_user_id=supervisor;select id into w from public.company_workers where company_id=c and auth_user_id=employee;
 execute 'set local role authenticated';
 denied:=false;begin perform public.save_essential_department(c,l,'Production');exception when others then denied:=true;end;if not denied then raise exception 'Base plan obtained departments';end if;
 denied:=false;begin perform public.save_essential_location(c,'Second location');exception when others then denied:=true;end;if not denied then raise exception 'Base plan exceeded location limit';end if;
 execute 'reset role';select user_id into owner_id from private.platform_owner;
 perform set_config('request.jwt.claim.sub',owner_id::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',owner_id,'aal','aal2')::text,true);execute 'set local role authenticated';
 denied:=false;begin perform public.platform_set_essential_test_plan(c,'essential_pro');exception when others then denied:=true;end;if not denied then raise exception 'Production company received simulated plan';end if;
 execute 'reset role';update public.companies set is_test=true,billing_mode='test_simulated' where id=c;execute 'set local role authenticated';perform public.platform_set_essential_test_plan(c,'essential_pro');
 perform set_config('request.jwt.claim.sub',boss::text,true);
 d:=public.save_essential_department(c,l,'Production');d2:=public.save_essential_department(c,l,'Administration');l2:=public.save_essential_location(c,'Succursale','Québec','America/Toronto');
 perform public.assign_essential_worker(sw,l,d);perform public.assign_essential_worker(w,l,d2);perform public.set_essential_supervisor(c,d,supervisor,true);
 nw:=public.create_essential_worker(c,'NO-AUTH','Alexandre','Martin',late||'@test.invalid');perform public.assign_essential_worker(nw.id,l,d);
 v_shift:=public.save_essential_shift(c,nw.id,l,d,'2026-11-03 23:00-05','2026-11-04 07:00-05','Nuit');
 if (select user_id from public.scheduled_shifts where id=v_shift) is not null then raise exception 'No-auth schedule fabricated an account';end if;
 denied:=false;begin perform public.save_essential_shift(c,nw.id,l,d,'2026-11-04 06:00-05','2026-11-04 10:00-05');exception when others then denied:=true;end;if not denied then raise exception 'Overlap accepted';end if;
 v_ids:=public.repeat_essential_shifts(c,w,l,d2,'2026-11-09',2,array[1,3,5],'23:00','07:00',v_request,'Rotation nuit');
 if cardinality(v_ids)<>6 then raise exception 'Wrong recurring shift count';end if;
 v_retry:=public.repeat_essential_shifts(c,w,l,d2,'2026-11-09',2,array[1,3,5],'23:00','07:00',v_request,'Rotation nuit');if v_ids<>v_retry then raise exception 'Recurring replay duplicated shifts';end if;
 denied:=false;begin perform public.repeat_essential_shifts(c,w,l,d2,'2026-03-08',1,array[7],'02:30','06:00',gen_random_uuid());exception when others then denied:=true;end;if not denied then raise exception 'Nonexistent DST wall time accepted';end if;
 denied:=false;begin perform public.repeat_essential_shifts(c,w,l,d2,'2026-11-01',1,array[7],'01:30','06:00',gen_random_uuid());exception when others then denied:=true;end;if not denied then raise exception 'Ambiguous DST wall time accepted';end if;
 perform set_config('request.jwt.claim.sub',supervisor::text,true);
 v_roster:=public.essential_team_roster(c);if v_roster::text like '%'||employee::text||'%' or exists(select 1 from jsonb_array_elements(v_roster) x where x->>'id'=w::text) then raise exception 'Supervisor saw another department';end if;
 if v_roster::text like '%email%' or v_roster::text like '%phone%' then raise exception 'Roster exposes private contact fields';end if;
 if (select count(*) from public.scheduled_shifts where company_id=c and worker_id=w)>0 then raise exception 'RLS exposes another department';end if;
 denied:=false;begin perform public.save_essential_shift(c,w,l,d2,'2026-12-01 08:00-05','2026-12-01 16:00-05');exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'Supervisor planned outside scope';end if;
 perform public.save_essential_shift(c,nw.id,l,d,'2026-12-01 08:00-05','2026-12-01 16:00-05');
 denied:=false;begin perform public.set_essential_supervisor(c,d2,supervisor,true);exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'Supervisor granted own permissions';end if;
 perform set_config('request.jwt.claim.sub',employee::text,true);
 perform public.acknowledge_essential_shift(v_ids[1],1);
 denied:=false;begin perform public.acknowledge_essential_shift(v_shift,1);exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'Acknowledged colleague shift';end if;
 perform public.set_essential_availability(c,'2026-12-02 00:00-05','2026-12-03 00:00-05',false,'Indisponible');
 perform set_config('request.jwt.claim.sub',boss::text,true);
 denied:=false;begin perform public.save_essential_shift(c,w,l,d2,'2026-12-02 08:00-05','2026-12-02 16:00-05');exception when others then denied:=true;end;if not denied then raise exception 'Unavailability ignored';end if;
 invite:=public.create_worker_invitation(nw.id);perform set_config('request.jwt.claim.sub',late::text,true);perform public.accept_worker_invitation(invite->>'token');
 if (select user_id from public.scheduled_shifts where id=v_shift)<>late then raise exception 'Existing schedule not attached at activation';end if;
 perform set_config('request.jwt.claim.sub',outsider::text,true);
 if (select count(*) from public.essential_locations where company_id=c)<>0 or (select count(*) from public.scheduled_shifts where company_id=c)<>0 then raise exception 'Tenant isolation failed';end if;
 execute 'reset role';
 if (select count(*) from public.app_notifications where company_id=c and recipient_id=employee and kind='schedule')>1 then raise exception 'Recurring notification spam';end if;
end $$;
rollback;
